<?php
declare(strict_types=1);
session_start();
$configFile=__DIR__.'/config.php';
if(!is_file($configFile)){http_response_code(500);echo '<h1>Unreal File Catalog</h1><p>Copy <code>catalog/config.example.php</code> to <code>catalog/config.php</code> and edit the DB settings.</p>';exit;}
$config=require $configFile;
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function u(array $p=[]):string{return 'index.php'.($p?'?'.http_build_query($p):'');}
function admin():bool{return ($_SESSION['user']['role']??'')==='admin';}
function need_admin():void{if(!admin()){header('Location: '.u(['page'=>'login']));exit;}}
function csrf():string{$_SESSION['csrf']??=bin2hex(random_bytes(16));return $_SESSION['csrf'];}
function check_csrf():void{if(($_POST['csrf']??'')!==($_SESSION['csrf']??'')){throw new RuntimeException('Bad CSRF token');}}
function bytes_fmt(int $b):string{$u=['B','KB','MB','GB','TB'];$n=$b;$i=0;while($n>=1024&&$i<count($u)-1){$n/=1024;$i++;}return ($i?number_format($n,2):(string)$b).' '.$u[$i];}
function slug(string $s):string{$s=strtolower(trim($s));$s=preg_replace('/[^a-z0-9]+/','-',$s)??'';return trim($s,'-')?:'item';}
function clean(string $s):string{return trim(str_replace(["\0",'/',"\\"],['','.','.'],$s));}
function joinp(array $p):string{return implode('.',array_values(array_filter(array_map('clean',$p),fn($v)=>$v!=='')));}
function db(array $c):PDO{static $pdo;if($pdo)return $pdo;$d=$c['db'];$dsn='mysql:host='.$d['host'].';port='.(int)$d['port'].';dbname='.$d['database'].';charset='.($d['charset']??'utf8mb4');$pdo=new PDO($dsn,$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $pdo;}
function one(PDO $db,string $sql,array $a=[]):?array{$s=$db->prepare($sql);$s->execute($a);$r=$s->fetch();return $r?:null;}
function allq(PDO $db,string $sql,array $a=[]):array{$s=$db->prepare($sql);$s->execute($a);return $s->fetchAll();}
function runq(PDO $db,string $sql,array $a=[]):int{$s=$db->prepare($sql);$s->execute($a);return $s->rowCount();}
function flash(string $url,string $m):void{$_SESSION['flash']=$m;header('Location: '.$url);exit;}
function head_html(array $c,string $t):void{echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($t).'</title><style>body{margin:0;background:#0b1020;color:#eef3ff;font:14px system-ui,Segoe UI,Arial}a{color:#8ab4ff;text-decoration:none}a:hover{text-decoration:underline}header{background:#090d19;border-bottom:1px solid #2a375f;padding:14px 18px;display:flex;gap:16px;flex-wrap:wrap;align-items:center}nav a{background:#17213d;padding:6px 9px;border-radius:8px;margin-right:6px}main{max-width:1280px;margin:auto;padding:18px}.card{background:#121a31;border:1px solid #2a375f;border-radius:14px;padding:16px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.stat{background:#17213d;border:1px solid #2a375f;border-radius:12px;padding:12px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #2a375f;padding:8px;text-align:left;vertical-align:top}th{background:#17213d}.muted{color:#9fb0d0}.mono{font-family:Consolas,monospace}.button,button{background:#23325f;border:1px solid #3b5599;color:#eef3ff;padding:8px 11px;border-radius:8px;cursor:pointer}.danger{background:#4a1b25;border-color:#8c2e3e}input,select,textarea{background:#0d1428;color:#eef3ff;border:1px solid #2a375f;border-radius:8px;padding:8px}.msg{padding:10px 12px;border-radius:10px;margin-bottom:14px;background:#102744;border:1px solid #275a92}.err{background:#3b121b;border-color:#863040}.dep{display:inline-block;font-size:12px;padding:2px 7px;border-radius:999px;border:1px solid #2a375f;background:#17213d;margin:2px}.resolved{border-color:#1d8f54}.missing{border-color:#a63b43}.common{border-color:#5c6688}.package_only{border-color:#b48a2a}.scroll{overflow:auto;max-height:560px}.path{word-break:break-all}.small{font-size:12px}</style></head><body><header><strong>'.h($c['site_name']??'Unreal File Catalog').'</strong><nav><a href="'.h(u()).'">Games</a><a href="'.h(u(['page'=>'search'])).'">Search</a>';
if(admin())echo '<a href="'.h(u(['page'=>'admin'])).'">Admin</a><a href="'.h(u(['page'=>'logout'])).'">Logout '.h($_SESSION['user']['username']).'</a>';else echo '<a href="'.h(u(['page'=>'login'])).'">Admin Login</a>';echo '</nav></header><main>';if(isset($_SESSION['flash'])){echo '<div class="msg">'.h($_SESSION['flash']).'</div>';unset($_SESSION['flash']);}}
function foot_html():void{echo '</main></body></html>';}
function reader(array $c,string $e):void{$r=$c['engine_readers'][$e]['reader']??'';$p=realpath(__DIR__.'/'.$r);if(!$p||!is_file($p))throw new RuntimeException('Reader not found for '.$e);if(!class_exists('UnrealPackageReader',false))require_once $p;}
function refpath(int $ref,array $im,array $ex,array &$cache,array $seen=[]):string{if(!$ref)return '';if(isset($cache[$ref]))return $cache[$ref];if(isset($seen[$ref]))return '';$seen[$ref]=1;if($ref<0){$i=-$ref-1;$r=$im[$i]??null;if(!$r)return '';$outer=(int)($r['outerIndex']??$r['OuterIndex']??$r['outer']??0);$name=(string)($r['objectNameText']??($r['ObjectName']['text']??''));return $cache[$ref]=joinp([refpath($outer,$im,$ex,$cache,$seen),$name]);}$i=$ref-1;$r=$ex[$i]??null;if(!$r)return '';$outer=(int)($r['outerIndex']??$r['packageIndex']??$r['outer']??0);$name=(string)($r['objectNameText']??'');return $cache[$ref]=joinp([refpath($outer,$im,$ex,$cache,$seen),$name]);}
function rebuild_deps(PDO $db,array $c,int $fileId):void{runq($db,'DELETE FROM ue_dependencies WHERE file_id=?',[$fileId]);$f=one($db,'SELECT * FROM ue_files WHERE id=?',[$fileId]);if(!$f)return;$common=array_map('strtolower',$c['common_packages']??[]);$ins=$db->prepare('INSERT INTO ue_dependencies(file_id,import_id,required_package,required_object_path,resolved_file_id,resolved_export_id,status)VALUES(?,?,?,?,?,?,?)');foreach(allq($db,'SELECT * FROM ue_imports WHERE file_id=?',[$fileId]) as $i){$st='missing';$rf=null;$re=null;if((int)$i['is_common'])$st='common';elseif($i['relative_object_path']===''){$m=one($db,'SELECT id FROM ue_files WHERE game_id=? AND package_name=? AND id<>? ORDER BY uploaded_at DESC LIMIT 1',[$f['game_id'],$i['root_package'],$fileId]);if($m){$st='package_only';$rf=(int)$m['id'];}}else{$m=one($db,'SELECT e.id export_id,f.id file_id FROM ue_exports e JOIN ue_files f ON f.id=e.file_id WHERE f.game_id=? AND e.full_path=? AND f.id<>? ORDER BY f.uploaded_at DESC LIMIT 1',[$f['game_id'],$i['full_path'],$fileId]);if($m){$st='resolved';$rf=(int)$m['file_id'];$re=(int)$m['export_id'];}}$ins->execute([$fileId,$i['id'],$i['root_package'],$i['full_path'],$rf,$re,$st]);}}
function rebuild_game(PDO $db,array $c,int $gid):void{foreach(allq($db,'SELECT id FROM ue_files WHERE game_id=?',[$gid]) as $f)rebuild_deps($db,$c,(int)$f['id']);}
function failed(array $c,string $tmp,string $orig,string $game,string $why):void{if(!is_file($tmp))return;$d=rtrim($c['storage_path'],DIRECTORY_SEPARATOR).'/games/'.slug($game).'/unverified';if(!is_dir($d))@mkdir($d,0775,true);$n=date('Ymd_His').'_'.bin2hex(random_bytes(4)).'_'.preg_replace('/[^A-Za-z0-9._-]+/','_',basename($orig));@rename($tmp,$d.'/'.$n);@file_put_contents($d.'/'.$n.'.txt',$why);}
function scan_file(PDO $db,array $c,int $gid,string $tmp,string $orig,?int $uid):array{$g=one($db,'SELECT * FROM ue_games WHERE id=?',[$gid]);if(!$g)throw new RuntimeException('Game not found');$ext=strtolower(pathinfo($orig,PATHINFO_EXTENSION));if(!in_array($ext,$c['allowed_extensions'],true))throw new RuntimeException('Extension not allowed: '.$ext);$size=filesize($tmp)?:0;if($size<=0||$size>(int)$c['max_upload_bytes'])throw new RuntimeException('Bad file size');$md5=md5_file($tmp);$sha1=sha1_file($tmp);if(!$md5||!$sha1)throw new RuntimeException('Could not hash file');$dup=one($db,'SELECT id,original_name FROM ue_files WHERE md5=?',[$md5]);if($dup)return ['duplicate',(int)$dup['id'],'Duplicate MD5: '.$dup['original_name']];reader($c,$g['engine_key']);$pkg=new UnrealPackageReader($tmp);$issues=method_exists($pkg,'validatePackage')?$pkg->validatePackage():(method_exists($pkg,'getDebugErrors')?$pkg->getDebugErrors():[]);if($issues)throw new RuntimeException(implode("\n",array_map('strval',$issues)));$h=method_exists($pkg,'getHeader')?$pkg->getHeader():[];$names=$pkg->getNames();$imports=$pkg->getImports();$exports=$pkg->getExports();$pname=clean(pathinfo($orig,PATHINFO_FILENAME));$dir=rtrim($c['storage_path'],DIRECTORY_SEPARATOR).'/games/'.slug($g['slug']).'/verified';if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Could not create storage folder');$stored=$md5.'.'.$ext;$dest=$dir.'/'.$stored;if(!rename($tmp,$dest))throw new RuntimeException('Could not store upload');$rel='storage/games/'.slug($g['slug']).'/verified/'.$stored;$db->beginTransaction();try{$st=$db->prepare('INSERT INTO ue_files(game_id,package_name,original_name,stored_name,relative_path,extension,file_size,md5,sha1,package_guid,package_version,licensee_version,name_count,import_count,export_count,scan_status,uploaded_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$gid,$pname,$orig,$stored,$rel,$ext,$size,$md5,$sha1,(string)($h['guid']??''),(int)($h['version']??0),(int)($h['licensee']??($h['licenseeVersion']??0)),count($names),count($imports),count($exports),'verified',$uid]);$fid=(int)$db->lastInsertId();$sn=$db->prepare('INSERT INTO ue_names(file_id,name_index,name_text,flags)VALUES(?,?,?,?)');foreach($names as $i=>$n)$sn->execute([$fid,$i,(string)($n['name']??$n['text']??''),isset($n['flags'])?(int)$n['flags']:null]);$cache=[];$common=array_map('strtolower',$c['common_packages']??[]);$si=$db->prepare('INSERT INTO ue_imports(file_id,import_index,class_package,class_name,object_name,outer_index,full_path,root_package,relative_object_path,is_common)VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($imports as $i=>$im){$full=refpath(-($i+1),$imports,$exports,$cache);$parts=$full?explode('.',$full):[];$root=$parts[0]??'';$relobj=count($parts)>1?implode('.',array_slice($parts,1)):'';$obj=(string)($im['objectNameText']??($im['ObjectName']['text']??''));$cp=(string)($im['classPackageText']??($im['ClassPackage']['text']??''));$cn=(string)($im['classNameText']??($im['ClassName']['text']??''));$si->execute([$fid,$i,$cp,$cn,$obj,(int)($im['outerIndex']??$im['OuterIndex']??$im['outer']??0),$full,$root,$relobj,in_array(strtolower($root),$common,true)?1:0]);}$se=$db->prepare('INSERT INTO ue_exports(file_id,export_index,class_name,object_name,outer_index,local_path,full_path,object_flags,serial_size,serial_offset)VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($exports as $i=>$ex){$local=refpath($i+1,$imports,$exports,$cache);$classRef=(int)($ex['classIndex']??$ex['class']??0);$class=$classRef?refpath($classRef,$imports,$exports,$cache):'';$se->execute([$fid,$i,$class,(string)($ex['objectNameText']??''),(int)($ex['outerIndex']??$ex['packageIndex']??$ex['outer']??0),$local,joinp([$pname,$local]),isset($ex['objectFlags'])?(int)$ex['objectFlags']:null,isset($ex['serialSize'])?(int)$ex['serialSize']:null,isset($ex['serialOffset'])?(int)$ex['serialOffset']:null]);}rebuild_deps($db,$c,$fid);$db->commit();rebuild_game($db,$c,$gid);return ['verified',$fid,'Uploaded and scanned'];}catch(Throwable $e){$db->rollBack();@unlink($dest);throw $e;}}
$db=db($config);$page=$_GET['page']??'home';
try{
if($page==='logout'){session_destroy();header('Location: '.u());exit;}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$cnt=(int)(one($db,'SELECT COUNT(*) c FROM ue_users')['c']??0);if($cnt===0){$un=trim((string)$_POST['username']);$pw=(string)$_POST['password'];if($un===''||strlen($pw)<8)throw new RuntimeException('Username required and password must be at least 8 characters');runq($db,'INSERT INTO ue_users(username,password_hash,role)VALUES(?,?,?)',[$un,password_hash($pw,PASSWORD_DEFAULT),'admin']);}$user=one($db,'SELECT * FROM ue_users WHERE username=?',[trim((string)$_POST['username'])]);if(!$user||!password_verify((string)$_POST['password'],$user['password_hash']))throw new RuntimeException('Invalid login');$_SESSION['user']=['id'=>(int)$user['id'],'username'=>$user['username'],'role'=>$user['role']];flash(u(['page'=>'admin']),'Logged in');}
if($page==='upload'&&$_SERVER['REQUEST_METHOD']==='POST'){need_admin();check_csrf();$gid=(int)$_POST['game_id'];$g=one($db,'SELECT * FROM ue_games WHERE id=?',[$gid]);if(!$g)throw new RuntimeException('Game not found');$ok=$dup=$bad=0;$msg=[];foreach($_FILES['files']['tmp_name']??[] as $i=>$tmp){$name=(string)($_FILES['files']['name'][$i]??'upload.bin');$err=(int)($_FILES['files']['error'][$i]??UPLOAD_ERR_NO_FILE);if($err!==UPLOAD_ERR_OK){$bad++;$msg[]=$name.': upload error '.$err;continue;}try{$r=scan_file($db,$config,$gid,$tmp,$name,$_SESSION['user']['id']??null);if($r[0]==='duplicate')$dup++;else $ok++;$msg[]=$name.': '.$r[2];}catch(Throwable $e){$bad++;failed($config,$tmp,$name,$g['slug'],$e->getMessage());$msg[]=$name.': failed - '.$e->getMessage();}}flash(u(['page'=>'game','id'=>$gid]),'Upload complete. Verified='.$ok.' Duplicate='.$dup.' Failed='.$bad.'. '.implode(' | ',array_slice($msg,0,5)));}
if($page==='save_game'&&$_SERVER['REQUEST_METHOD']==='POST'){need_admin();check_csrf();runq($db,'INSERT INTO ue_games(name,slug,engine_key,description)VALUES(?,?,?,?)',[trim((string)$_POST['name']),slug((string)$_POST['slug']),(string)$_POST['engine_key'],trim((string)$_POST['description'])]);flash(u(['page'=>'admin']),'Game saved');}
if($page==='save_file'&&$_SERVER['REQUEST_METHOD']==='POST'){need_admin();check_csrf();$id=(int)$_POST['id'];runq($db,'UPDATE ue_files SET package_name=? WHERE id=?',[clean((string)$_POST['package_name']),$id]);$f=one($db,'SELECT game_id FROM ue_files WHERE id=?',[$id]);if($f)rebuild_game($db,$config,(int)$f['game_id']);flash(u(['page'=>'file','id'=>$id]),'Package name saved and links rebuilt');}
if($page==='delete_file'&&$_SERVER['REQUEST_METHOD']==='POST'){need_admin();check_csrf();$id=(int)$_POST['id'];$f=one($db,'SELECT * FROM ue_files WHERE id=?',[$id]);if($f){runq($db,'DELETE FROM ue_files WHERE id=?',[$id]);$p=__DIR__.'/'.$f['relative_path'];if(is_file($p))@unlink($p);rebuild_game($db,$config,(int)$f['game_id']);}flash(u(['page'=>'admin']),'File deleted');}
if($page==='download'){$id=(int)($_GET['id']??0);$f=one($db,'SELECT * FROM ue_files WHERE id=?',[$id]);if(!$f)throw new RuntimeException('File not found');$p=realpath(__DIR__.'/'.$f['relative_path']);$root=realpath(rtrim($config['storage_path'],DIRECTORY_SEPARATOR));if(!$p||!$root||!str_starts_with($p,$root)||!is_file($p))throw new RuntimeException('Stored file missing');header('Content-Type: application/octet-stream');header('Content-Length: '.filesize($p));header('Content-Disposition: attachment; filename="'.addslashes($f['original_name']).'"');readfile($p);exit;}
head_html($config,'Unreal File Catalog');
if($page==='home'){$games=allq($db,'SELECT g.*,COUNT(f.id) file_count,COALESCE(SUM(f.file_size),0) total_size FROM ue_games g LEFT JOIN ue_files f ON f.game_id=g.id GROUP BY g.id ORDER BY g.name');echo '<div class="card"><h1>Unreal Games</h1><p class="muted">Browse verified Unreal packages, dependencies, imports, exports and MD5 hashes.</p></div><div class="grid">';foreach($games as $g)echo '<a class="stat" href="'.h(u(['page'=>'game','id'=>$g['id']])).'"><h2>'.h($g['name']).'</h2><p>'.h($g['engine_key']).'</p><p>'.(int)$g['file_count'].' files / '.h(bytes_fmt((int)$g['total_size'])).'</p></a>';echo '</div>';}
elseif($page==='game'){$gid=(int)($_GET['id']??0);$g=one($db,'SELECT * FROM ue_games WHERE id=?',[$gid]);if(!$g)throw new RuntimeException('Game not found');echo '<div class="card"><h1>'.h($g['name']).'</h1><p class="muted">'.h($g['description']).'</p></div>';$files=allq($db,"SELECT f.*,SUM(d.status='resolved') resolved_count,SUM(d.status='missing') missing_count,SUM(d.status='package_only') package_only_count,SUM(d.status='common') common_count FROM ue_files f LEFT JOIN ue_dependencies d ON d.file_id=f.id WHERE f.game_id=? GROUP BY f.id ORDER BY f.package_name,f.original_name",[$gid]);echo '<div class="card"><h2>Files</h2><div class="scroll"><table><tr><th>Package</th><th>File</th><th>MD5</th><th>Size</th><th>Dependencies</th><th>Actions</th></tr>';foreach($files as $f){$deps='';foreach(['resolved','missing','package_only','common'] as $k){$n=(int)($f[$k.'_count']??0);if($n)$deps.='<span class="dep '.$k.'">'.$k.': '.$n.'</span>';}$deps=$deps?:'<span class="muted">none</span>';echo '<tr><td class="mono">'.h($f['package_name']).'</td><td>'.h($f['original_name']).'<br><span class="muted small">GUID '.h($f['package_guid']).'</span></td><td class="mono small">'.h($f['md5']).'</td><td>'.h(bytes_fmt((int)$f['file_size'])).'</td><td>'.$deps.'</td><td><a href="'.h(u(['page'=>'file','id'=>$f['id']])).'">details</a> | <a href="'.h(u(['page'=>'examine','id'=>$f['id']])).'">examine</a> | <a href="'.h(u(['page'=>'download','id'=>$f['id']])).'">download</a></td></tr>';}echo '</table></div></div>';if(admin())echo '<div class="card"><h2>Upload files</h2><form method="post" enctype="multipart/form-data" action="'.h(u(['page'=>'upload'])).'"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="game_id" value="'.$gid.'"><p class="muted">Max per file: '.h(bytes_fmt((int)$config['max_upload_bytes'])).'. Failed scans move to the admin-only unverified folder.</p><input type="file" name="files[]" multiple required> <button>Upload and scan</button></form></div>';}
elseif($page==='file'){$id=(int)($_GET['id']??0);$f=one($db,'SELECT f.*,g.name game_name FROM ue_files f JOIN ue_games g ON g.id=f.game_id WHERE f.id=?',[$id]);if(!$f)throw new RuntimeException('File not found');echo '<div class="card"><h1>'.h($f['package_name']).'</h1><p>'.h($f['original_name']).' / '.h($f['game_name']).'</p><p><a class="button" href="'.h(u(['page'=>'download','id'=>$id])).'">Download</a> <a class="button" href="'.h(u(['page'=>'examine','id'=>$id])).'">Examine full parse</a></p><div class="grid"><div class="stat">MD5<br><span class="mono small">'.h($f['md5']).'</span></div><div class="stat">SHA1<br><span class="mono small">'.h($f['sha1']).'</span></div><div class="stat">GUID<br><span class="mono small">'.h($f['package_guid']).'</span></div><div class="stat">Tables<br>'.(int)$f['name_count'].' names / '.(int)$f['import_count'].' imports / '.(int)$f['export_count'].' exports</div></div></div>';$deps=allq($db,'SELECT d.*,rf.original_name resolved_file FROM ue_dependencies d LEFT JOIN ue_files rf ON rf.id=d.resolved_file_id WHERE d.file_id=? ORDER BY FIELD(d.status,"missing","package_only","resolved","common"),d.required_package,d.required_object_path',[$id]);echo '<div class="card"><h2>Dependencies</h2><table><tr><th>Status</th><th>Required object</th><th>Resolved by</th></tr>';foreach($deps as $d)echo '<tr><td><span class="dep '.h($d['status']).'">'.h($d['status']).'</span></td><td class="mono path">'.h($d['required_object_path']).'</td><td>'.($d['resolved_file_id']?'<a href="'.h(u(['page'=>'file','id'=>$d['resolved_file_id']])).'">'.h($d['resolved_file']).'</a>':'<span class="muted">not resolved</span>').'</td></tr>';echo '</table></div>';if(admin())echo '<div class="card"><h2>Admin</h2><form method="post" action="'.h(u(['page'=>'save_file'])).'"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="id" value="'.$id.'">Package name <input name="package_name" value="'.h($f['package_name']).'"> <button>Save and rebuild links</button></form><form method="post" action="'.h(u(['page'=>'delete_file'])).'" onsubmit="return confirm(\'Delete this file and DB rows?\')"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="id" value="'.$id.'"><button class="danger">Delete file</button></form></div>';}
elseif($page==='examine'){$id=(int)($_GET['id']??0);$f=one($db,'SELECT f.*,g.engine_key FROM ue_files f JOIN ue_games g ON g.id=f.game_id WHERE f.id=?',[$id]);if(!$f)throw new RuntimeException('File not found');reader($config,$f['engine_key']);$pkg=new UnrealPackageReader(__DIR__.'/'.$f['relative_path']);echo '<div class="card"><h1>Examine: '.h($f['original_name']).'</h1><p><a href="'.h(u(['page'=>'file','id'=>$id])).'">Back</a></p></div>';foreach(['Header'=>$pkg->getHeader(),'Names'=>$pkg->getNames(),'Imports'=>$pkg->getImports(),'Exports'=>$pkg->getExports()] as $label=>$data)echo '<div class="card"><h2>'.h($label).'</h2><div class="scroll"><pre class="mono">'.h(json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)).'</pre></div></div>';}
elseif($page==='search'){$q=trim((string)($_GET['q']??''));echo '<div class="card"><h1>Search</h1><form><input type="hidden" name="page" value="search"><input name="q" value="'.h($q).'" placeholder="MD5, SHA1, GUID, package, import/export object, file name" style="min-width:420px"> <button>Search</button></form></div>';if($q!==''){$like='%'.$q.'%';$rows=allq($db,'SELECT DISTINCT f.* FROM ue_files f LEFT JOIN ue_imports i ON i.file_id=f.id LEFT JOIN ue_exports e ON e.file_id=f.id WHERE f.md5=? OR f.sha1=? OR f.package_guid LIKE ? OR f.package_name LIKE ? OR f.original_name LIKE ? OR i.full_path LIKE ? OR e.full_path LIKE ? ORDER BY f.package_name LIMIT 200',[$q,$q,$like,$like,$like,$like,$like]);echo '<div class="card"><h2>Results</h2><table><tr><th>Package</th><th>File</th><th>MD5</th><th>Open</th></tr>';foreach($rows as $r)echo '<tr><td class="mono">'.h($r['package_name']).'</td><td>'.h($r['original_name']).'</td><td class="mono small">'.h($r['md5']).'</td><td><a href="'.h(u(['page'=>'file','id'=>$r['id']])).'">details</a></td></tr>';echo '</table></div>';}}
elseif($page==='login'){$cnt=(int)(one($db,'SELECT COUNT(*) c FROM ue_users')['c']??0);echo '<div class="card"><h1>'.($cnt?'Admin Login':'Create first admin user').'</h1><form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><p><input name="username" required placeholder="Username"></p><p><input type="password" name="password" required placeholder="Password"></p><button>'.($cnt?'Login':'Create admin').'</button></form></div>';}
elseif($page==='admin'){need_admin();$games=allq($db,'SELECT * FROM ue_games ORDER BY name');echo '<div class="card"><h1>Admin</h1></div><div class="card"><h2>Games</h2><table><tr><th>Name</th><th>Slug</th><th>Engine</th><th>Open</th></tr>';foreach($games as $g)echo '<tr><td>'.h($g['name']).'</td><td>'.h($g['slug']).'</td><td>'.h($g['engine_key']).'</td><td><a href="'.h(u(['page'=>'game','id'=>$g['id']])).'">open</a></td></tr>';echo '</table></div><div class="card"><h2>Add game</h2><form method="post" action="'.h(u(['page'=>'save_game'])).'"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input name="name" required placeholder="Game name"> <input name="slug" required placeholder="slug"> <select name="engine_key">';foreach($config['engine_readers'] as $k=>$v)echo '<option value="'.h($k).'">'.h($k.' - '.$v['label']).'</option>';echo '</select><p><textarea name="description" rows="3" style="width:100%" placeholder="Description"></textarea></p><button>Save game</button></form></div>';}
else throw new RuntimeException('Unknown page');foot_html();
}catch(Throwable $e){if(!headers_sent()){http_response_code(500);head_html($config,'Error');}echo '<div class="msg err"><strong>Error:</strong> '.h($e->getMessage()).'</div>';foot_html();}
